const moduloA = { duplicar: n => n * 2, triplicar: n => n * 3 };
const moduloB = { mayusculas: s => s.toUpperCase(), minusculas: s => s.toLowerCase() };
const moduloC = { hoy: () => new Date().getFullYear() };

// Barrel file: unifica los tres módulos
const barrel = {
  ...moduloA,
  ...moduloB,
  ...moduloC,
};

const r1 = barrel.duplicar(7);
const r2 = barrel.mayusculas('hola');
const tieneHoy = typeof barrel.hoy === 'function';

console.log(r1, r2, tieneHoy);

const moduloPagos = { procesar: (monto) => 'Pago: $' + monto };
const moduloEnvios = { procesar: (paquete) => 'Enviando: ' + paquete };

// Barrel con alias para resolver la colisión
const barrel = {
  procesarPago: moduloPagos.procesar,
  procesarEnvio: moduloEnvios.procesar,
};

const rPago = barrel.procesarPago(1500);
const rEnvio = barrel.procesarEnvio('Libro');
const tieneConflicto = 'procesar' in barrel;

console.log(rPago, rEnvio, tieneConflicto);

exercises.prompt:
Estás construyendo una librería `FormKit`. Tienes módulos internos y debes crear un barrel que exponga solo la API pública.

Módulos internos:
```javascript
const _internos = {
  _validarTipo: (v, t) => typeof v === t,      // Privado
  _normalizarString: s => s.trim().toLowerCase(), // Privado
};

const campos = {
  texto: (valor) => typeof valor === 'string' && valor.trim().length > 0,
  numero: (valor) => typeof valor === 'number' && !isNaN(valor),
  email: (valor) => /^[^@]+@[^@]+\.[^@]+$/.test(valor),
};

const formulario = {
  validar: (datos, reglas) => {
    const errores = {};
    for (const campo in reglas) {
      if (!reglas[campo](datos[campo])) errores[campo] = 'inválido';
    }
    return { valido: Object.keys(errores).length === 0, errores };
  },
};
```

Crea `FormKit` como barrel público que exponga SOLO:
- `validarCampo` (alias de `campos`)
- `validarFormulario` (alias de `formulario.validar`)
- NO exponer `_internos`

Prueba con un formulario de login.

exercises.starterCode:
const _internos = {
  _validarTipo: (v, t) => typeof v === t,
  _normalizarString: s => s.trim().toLowerCase(),
};

const campos = {
  texto: (valor) => typeof valor === 'string' && valor.trim().length > 0,
  numero: (valor) => typeof valor === 'number' && !isNaN(valor),
  email: (valor) => /^[^@]+@[^@]+\.[^@]+$/.test(valor),
};

const formulario = {
  validar: (datos, reglas) => {
    const errores = {};
    for (const campo in reglas) {
      if (!reglas[campo](datos[campo])) errores[campo] = 'inválido';
    }
    return { valido: Object.keys(errores).length === 0, errores };
  },
};

// API pública del barrel
const FormKit = {
  validarCampo: campos,
  validarFormulario: formulario.validar,
};

// Prueba
const loginData = { usuario: 'ana', email: 'ana@test.com', edad: 25 };
const loginReglas = {
  usuario: FormKit.validarCampo.texto,
  email: FormKit.validarCampo.email,
  edad: FormKit.validarCampo.numero,
};

const resultadoValido = FormKit.validarFormulario(loginData, loginReglas);
const resultadoInvalido = FormKit.validarFormulario(
  { usuario: '', email: 'no-es-email', edad: NaN },
  loginReglas
);

console.log(resultadoValido);
console.log(resultadoInvalido);
